// 数据访问助手函数
const LegoData = {
    // 获取主题数据
    getThemeById(id) {
        return FACTORY_DATA.find(t => t.id === id);
    },
    
    // 获取主题的弦图数据
    getChordData(themeId) {
        return CHORD_DATA_MAP[themeId] || null;
    },
    
    // 获取主题的时间线数据
    getTimelineData(themeId) {
        return TIMELINE_DATA_MAP[themeId] || null;
    },
    
    // 获取随机主题
    getRandomTheme() {
        return FACTORY_DATA[Math.floor(Math.random() * FACTORY_DATA.length)];
    },
    
    // 获取Top N主题
    getTopThemes(n = 10) {
        return [...FACTORY_DATA].sort((a, b) => b.value - a.value).slice(0, n);
    },
    
    // 根据年份过滤
    getThemesByYearRange(startYear, endYear) {
        return FACTORY_DATA.filter(t => t.year_avg >= startYear && t.year_avg <= endYear);
    },
    
    // 获取复杂度最高的主题
    getMostComplexThemes(n = 5) {
        return [...FACTORY_DATA].sort((a, b) => b.complexity - a.complexity).slice(0, n);
    },
    
    // 获取创新度最高的主题
    getMostInnovativeThemes(n = 5) {
        return [...FACTORY_DATA].sort((a, b) => b.innovation - a.innovation).slice(0, n);
    }
};

// 导出数据
window.LEGO_DATA = {
    STATS_SUMMARY,
    FACTORY_DATA,
    CHORD_DATA_MAP,
    TIMELINE_DATA_MAP,
    NETWORK_DATA,
    SCATTER_DATA,
    COLOR_MAP,
    THEME_HIERARCHY,
    LegoData,
    version: LEGO_DATA_VERSION,
    generated: DATA_GENERATED
};
